import { useCallback, useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import "../css/homepage.css";
import "../css/Mybooking.css";

const API_BASE_URL = "http://localhost:5001";

function getStoredUser() {
  try {
    return JSON.parse(localStorage.getItem("user") || "null");
  } catch (error) {
    console.error("Unable to read user data:", error);
    return null;
  }
}

function formatDate(dateValue) {
  if (!dateValue) return "-";

  const date = new Date(dateValue);

  if (Number.isNaN(date.getTime())) {
    return String(dateValue);
  }

  return date.toLocaleDateString("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });
}

function formatTime(timeValue) {
  if (!timeValue) return "-";

  const value = String(timeValue);

  // Keep HH:mm or HH:mm:ss values readable.
  const match = value.match(/^(\d{1,2}):(\d{2})/);

  if (match) {
    return `${match[1].padStart(2, "0")}:${match[2]}`;
  }

  const date = new Date(value);

  if (!Number.isNaN(date.getTime())) {
    return date.toLocaleTimeString("en-GB", {
      hour: "2-digit",
      minute: "2-digit",
      hour12: false,
    });
  }

  return value;
}

function getStatus(status) {
  const value = String(status || "pending").toLowerCase();

  if (
    ["cancelled", "canceled", "rejected", "expired"].includes(value)
  ) {
    return {
      label: value === "canceled" ? "Cancelled" :
        value.charAt(0).toUpperCase() + value.slice(1),
      className: "cancelled",
    };
  }

  if (
    ["confirmed", "approved", "success"].includes(value)
  ) {
    return {
      label: value === "success" ? "Confirmed" :
        value.charAt(0).toUpperCase() + value.slice(1),
      className: "confirmed",
    };
  }

  if (["completed", "finished"].includes(value)) {
    return {
      label: "Completed",
      className: "completed",
    };
  }

  return {
    label: value.charAt(0).toUpperCase() + value.slice(1),
    className: "pending",
  };
}

function getUserId(user) {
  return user?.id ?? user?.user_id ?? user?.userId ?? null;
}

function Mybooking() {
  const navigate = useNavigate();

  const [user] = useState(() => getStoredUser());
  const [bookings, setBookings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [cancellingId, setCancellingId] = useState(null);
  const [notice, setNotice] = useState("");
  const [profileOpen, setProfileOpen] = useState(false);

  const userId = getUserId(user);

  useEffect(() => {
    if (!user || !userId) {
      navigate("/", { replace: true });
    }
  }, [user, userId, navigate]);

  const fetchBookings = useCallback(async () => {
    if (!userId) {
      setLoading(false);
      return;
    }

    setLoading(true);
    setError("");

    try {
      const token = localStorage.getItem("token");

      const response = await fetch(
        `${API_BASE_URL}/api/bookings/${encodeURIComponent(userId)}`,
        {
          method: "GET",
          headers: {
            Accept: "application/json",
            ...(token
              ? { Authorization: `Bearer ${token}` }
              : {}),
          },
        }
      );

      const data = await response.json().catch(() => ({}));

      if (!response.ok) {
        throw new Error(
          data.message || "Unable to load your bookings."
        );
      }

      const bookingList = Array.isArray(data)
        ? data
        : Array.isArray(data.bookings)
          ? data.bookings
          : [];

      setBookings(bookingList);
    } catch (err) {
      console.error("Failed to fetch bookings:", err);
      setError(
        err.message ||
          "Something went wrong while loading your bookings."
      );
    } finally {
      setLoading(false);
    }
  }, [userId]);

  useEffect(() => {
    if (userId) {
      fetchBookings();
    }
  }, [userId, fetchBookings]);

  const handleCancel = async (booking) => {
    const bookingId = booking.id ?? booking.booking_id;

    if (bookingId == null) {
      setNotice("");
      setError("Unable to identify this booking.");
      return;
    }

    const status = getStatus(booking.status);

    if (
      ["cancelled", "completed"].includes(
        status.className
      )
    ) {
      return;
    }

    const confirmed = window.confirm(
      "Are you sure you want to cancel this booking?"
    );

    if (!confirmed) return;

    setCancellingId(bookingId);
    setError("");
    setNotice("");

    try {
      const token = localStorage.getItem("token");

      const response = await fetch(
        `${API_BASE_URL}/api/bookings/${encodeURIComponent(bookingId)}`,
        {
          method: "DELETE",
          headers: {
            Accept: "application/json",
            "Content-Type": "application/json",
            "X-User-Id": String(userId),
            ...(token
              ? { Authorization: `Bearer ${token}` }
              : {}),
          },
        }
      );

      const data = await response.json().catch(() => ({}));

      if (!response.ok || data.success === false) {
        throw new Error(
          data.message || "Unable to cancel this booking."
        );
      }

      setNotice(data.message || "Booking cancelled successfully.");
      await fetchBookings();
    } catch (err) {
      console.error("Failed to cancel booking:", err);
      setError(
        err.message || "Something went wrong while cancelling."
      );
    } finally {
      setCancellingId(null);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem("user");
    localStorage.removeItem("token");
    navigate("/", { replace: true });
  };

  const displayName =
    user?.name ||
    user?.full_name ||
    user?.username ||
    user?.email ||
    "My Account";

  return (
    <div className="homepage mybooking-page">
      <header className="topbar">
        <a
          className="brand"
          href="/"
          aria-label="Go to homepage"
          onClick={(event) => {
            event.preventDefault();
            navigate("/");
          }}
        >
          <span className="brand-mark">R</span>
          <span className="brand-name">
            ROOM<span>RESERVE</span>
          </span>
        </a>

        <nav className="nav-menu" aria-label="Main navigation">
          <a href="/" onClick={(e) => {
            e.preventDefault();
            navigate("/");
          }}>
            HOME
          </a>

          <a
            href="/mybooking"
            className="active"
            aria-current="page"
            onClick={(e) => e.preventDefault()}
          >
            MY BOOKING
          </a>

          <a href="/guide" onClick={(e) => {
            e.preventDefault();
            navigate("/guide");
          }}>
            GUIDE
          </a>

          <a href="/rule" onClick={(e) => {
            e.preventDefault();
            navigate("/rule");
          }}>
            RULE
          </a>

          <a href="/review" onClick={(e) => {
            e.preventDefault();
            navigate("/review");
          }}>
            REVIEW
          </a>
        </nav>

        <div className="nav-right">
          <button
            type="button"
            className="profile-button"
            aria-expanded={profileOpen}
            onClick={() => setProfileOpen((open) => !open)}
          >
            <span className="profile-avatar">
              {displayName.charAt(0).toUpperCase()}
            </span>
            <span className="profile-name">{displayName}</span>
            <span className="profile-arrow">
              {profileOpen ? "▲" : "▼"}
            </span>
          </button>

          {profileOpen && (
            <div className="profile-dropdown">
              <button
                type="button"
                onClick={() => navigate("/")}
              >
                Home
              </button>
              <button type="button" onClick={handleLogout}>
                Log out
              </button>
            </div>
          )}
        </div>
      </header>

      <main className="mybooking-main">
        <section className="mybooking-hero">
          <div className="mybooking-hero-content">
            <p className="mybooking-eyebrow">YOUR SPACE, YOUR TIME</p>
            <h1>My Booking</h1>
            <p>
              Manage your reservations and keep track of your
              upcoming room bookings.
            </p>
          </div>

          <div className="mybooking-hero-decoration" aria-hidden="true">
            <span className="decoration-circle circle-one" />
            <span className="decoration-circle circle-two" />
            <span className="decoration-circle circle-three" />
          </div>
        </section>

        <section className="booking-section">
          <div className="booking-section-heading">
            <div>
              <p className="section-eyebrow">OVERVIEW</p>
              <h2>Your Reservations</h2>
              <p className="section-description">
                View the details and status of your bookings.
              </p>
            </div>

            <button
              type="button"
              className="refresh-button"
              onClick={() => {
                setNotice("");
                fetchBookings();
              }}
              disabled={loading}
            >
              <span aria-hidden="true">↻</span>
              Refresh
            </button>
          </div>

          {!loading && !error && (
            <div className="booking-summary">
              <div className="summary-icon" aria-hidden="true">
                ▣
              </div>
              <div>
                <span className="summary-label">
                  Total reservations
                </span>
                <strong>{bookings.length}</strong>
              </div>
            </div>
          )}

          {notice && (
            <div className="booking-alert success-alert" role="status">
              <span aria-hidden="true">✓</span>
              {notice}
              <button
                type="button"
                aria-label="Dismiss message"
                onClick={() => setNotice("")}
              >
                ×
              </button>
            </div>
          )}

          {error && (
            <div className="booking-alert error-alert" role="alert">
              <span aria-hidden="true">!</span>
              <span>{error}</span>
              <button
                type="button"
                className="alert-retry"
                onClick={fetchBookings}
                disabled={loading}
              >
                Try again
              </button>
            </div>
          )}

          {loading ? (
            <div className="booking-state">
              <span className="booking-spinner" />
              <h3>Loading your bookings...</h3>
              <p>Please wait while we retrieve your reservations.</p>
            </div>
          ) : error ? (
            <div className="booking-state">
              <div className="state-icon error-state-icon">!</div>
              <h3>Unable to load bookings</h3>
              <p>Please check your connection and try again.</p>
              <button
                type="button"
                className="primary-button"
                onClick={fetchBookings}
              >
                Try again
              </button>
            </div>
          ) : bookings.length === 0 ? (
            <div className="booking-state empty-booking-state">
              <div className="state-icon" aria-hidden="true">
                ▢
              </div>
              <h3>No bookings yet</h3>
              <p>
                You haven't made any reservations. Find a room
                and make your first booking.
              </p>
              <button
                type="button"
                className="primary-button"
                onClick={() => navigate("/")}
              >
                Explore rooms
                <span aria-hidden="true"> →</span>
              </button>
            </div>
          ) : (
            <div className="booking-list">
              {bookings.map((booking, index) => {
                const bookingId =
                  booking.id ?? booking.booking_id ?? index;

                const roomName =
                  booking.room_name ||
                  booking.room ||
                  booking.roomName ||
                  "Room";

                const bookingDate =
                  booking.booking_date ||
                  booking.date ||
                  booking.bookingDate;

                const status = getStatus(booking.status);

                const canCancel = ![
                  "cancelled",
                  "completed",
                ].includes(status.className);

                return (
                  <article
                    className="booking-card"
                    key={bookingId}
                  >
                    <div className="booking-card-accent" />

                    <div className="booking-card-main">
                      <div className="booking-card-top">
                        <div className="room-heading">
                          <div className="room-icon" aria-hidden="true">
                            <svg
                              viewBox="0 0 24 24"
                              fill="none"
                              stroke="currentColor"
                              strokeWidth="1.7"
                              strokeLinecap="round"
                              strokeLinejoin="round"
                            >
                              <path d="M3 21V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2v16" />
                              <path d="M3 14h18M7 14V9h4v5m2 0V9h4v5M2 21h20" />
                            </svg>
                          </div>

                          <div>
                            <p className="room-label">RESERVED ROOM</p>
                            <h3>{roomName}</h3>
                          </div>
                        </div>

                        <span
                          className={`booking-status status-${status.className}`}
                        >
                          <span className="status-dot" />
                          {status.label}
                        </span>
                      </div>

                      <div className="booking-details">
                        <div className="booking-detail">
                          <span className="detail-icon" aria-hidden="true">
                            ▦
                          </span>
                          <div>
                            <span className="detail-label">Date</span>
                            <strong>{formatDate(bookingDate)}</strong>
                          </div>
                        </div>

                        <div className="booking-detail">
                          <span className="detail-icon" aria-hidden="true">
                            ◷
                          </span>
                          <div>
                            <span className="detail-label">Time</span>
                            <strong>
                              {formatTime(booking.start_time)} –{" "}
                              {formatTime(booking.end_time)}
                            </strong>
                          </div>
                        </div>

                        <div className="booking-detail">
                          <span className="detail-icon" aria-hidden="true">
                            #
                          </span>
                          <div>
                            <span className="detail-label">Booking ID</span>
                            <strong className="booking-id">
                              #{booking.id ?? booking.booking_id ?? "-"}
                            </strong>
                          </div>
                        </div>
                      </div>

                      <div className="booking-card-footer">
                        <span className="booking-footer-note">
                          {status.className === "cancelled"
                            ? "This reservation has been cancelled."
                            : status.className === "completed"
                              ? "This reservation is complete."
                              : "Please check your booking details."}
                        </span>

                        {canCancel && (
                          <button
                            type="button"
                            className="cancel-booking-button"
                            disabled={cancellingId === bookingId}
                            onClick={() => handleCancel(booking)}
                          >
                            {cancellingId === bookingId
                              ? "Cancelling..."
                              : "Cancel booking"}
                          </button>
                        )}
                      </div>
                    </div>
                  </article>
                );
              })}
            </div>
          )}
        </section>

        <footer className="mybooking-footer">
          <p>ROOM RESERVE</p>
          <span>Make room for what matters.</span>
        </footer>
      </main>
    </div>
  );
}

export default Mybooking;
